import { useEffect, useRef } from 'react';
import { Howl } from 'howler';
import { usePlayerStore } from '@/store/usePlayerStore';

export function useAudioEngine() {
  // Referensi memori untuk objek suara yang aktif, agar tidak terbuat ganda
  const soundRef = useRef<Howl | null>(null);
  const { currentTrack, isPlaying, nextTrack } = usePlayerStore();

  // Effect 1: Menangani pergantian lagu (currentTrack berubah)
  useEffect(() => {
    // Jika ada lagu sebelumnya yang masih jalan, hancurkan (unload) dari memori
    if (soundRef.current) {
      soundRef.current.unload();
    }

    if (currentTrack) {
      // Inisialisasi audio decoder baru
      soundRef.current = new Howl({
        src: [currentTrack.audioUrl],
        html5: true, // Wajib TRUE! Agar lagu besar di-stream via chunk, bukan didownload full
        volume: 1.0,
        onend: () => {
          // Trigger otomatis dari Howler jika lagu sudah habis durasinya
          nextTrack(); 
        }
      });

      // Langsung mainkan jika state di UI menyuruh main
      if (isPlaying) {
        soundRef.current.play();
      }
    }

    return () => {
      // Cleanup: Hancurkan memori jika komponen di-unmount (meskipun di arsitektur kita, ini jarang terjadi)
      if (soundRef.current) soundRef.current.unload();
    };
  }, [currentTrack]);

  // Effect 2: Menangani tombol Pause / Play ditekan user tanpa mengganti lagu
  useEffect(() => {
    if (!soundRef.current) return;

    if (isPlaying && !soundRef.current.playing()) {
      soundRef.current.play();
    } else if (!isPlaying && soundRef.current.playing()) {
      soundRef.current.pause();
    }
  }, [isPlaying]);
}

