export default function SeekBar() {
  const [progress, setProgress] = useState(0);
  const [currentTime, setCurrentTime] = useState('0:00');
  const { isPlaying } = usePlayerStore();
  const rafRef = useRef<number>();

  // Helper memformat detik menjadi menit:detik (contoh: 125 -> 2:05)
  const formatTime = (secs: number) => {
    const m = Math.floor(secs / 60);
    const s = Math.floor(secs % 60);
    return `${m}:${s < 10 ? '0' : ''}${s}`;
  };

  useEffect(() => {
    const updateProgress = () => {
      // Mengakses instance global dari lagu yang aktif
      const sound = Howler._howls[0];
      if (sound && sound.playing()) {
        const currentPos = sound.seek() as number;
        const duration = sound.duration();

        setProgress((currentPos / duration) * 100);
        setCurrentTime(formatTime(currentPos));
      }
      rafRef.current = requestAnimationFrame(updateProgress);
    };

    if (isPlaying) {
      rafRef.current = requestAnimationFrame(updateProgress);
    } else if (rafRef.current) {
      cancelAnimationFrame(rafRef.current);
    }

    return () => {
      if (rafRef.current) cancelAnimationFrame(rafRef.current);
    };
  }, [isPlaying]);

  return (
    <div className="w-full flex items-center gap-3 text-[11px] text-slate-400 font-mono">
